mapper.select:
/* file : PredictionMapper.xml, id : getPredictionList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'AUGMENT_STATUS' AND T.DTL_CD = A.AUGMENT_STATUS) STATUS_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_AUGMENT A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' ) TB
WHERE TITLE LIKE CONCAT('%', #{keyword}, '%')
/*||ORDER BY REG_DT DESC||*/

	/* file : PredictionMapper.xml, id : getPredictionListSetUserSeq */
	SELECT *
	  FROM (
			  SELECT A.*
			  , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'AUGMENT_STATUS' AND T.DTL_CD = A.AUGMENT_STATUS) STATUS_NM
			  , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID
			    FROM TB_AUGMENT A
			   WHERE A.DEL_YN = 'N'
	             AND A.USE_YN = 'Y'
	             AND A.REG_USER_SEQ = #{user_seq}
			) TB		

		 WHERE TITLE LIKE CONCAT('%', #{keyword}, '%')

/*||ORDER BY REG_DT DESC||*/

/* file : PredictionMapper.xml, id : getPredictionSharedList */ SELECT * FROM ( SELECT A.* , (SELECT DTL_CD_NM FROM TB_CODE_DTL T WHERE T.DEL_YN = 'N' AND T.GRP_CD = 'AUGMENT_STATUS' AND T.DTL_CD = A.AUGMENT_STATUS) STATUS_NM , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_AUGMENT A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' AND A.RLS_YN = 'Y' AND A.AUGMENT_STATUS = 'DONE' ) TB
WHERE TITLE LIKE CONCAT('%', #{sub_keyword}, '%')
/*||ORDER BY REG_DT DESC||*/

mapper.insert:
/* file : PredictionMapper.xml, id : insertAugmentInfo */
INSERT
  INTO TB_AUGMENT (
              TITLE
            , DERPN
            , PPRCS_SEQ
            , MODEL_SEQ
            , DATA_TP
            , AUGMENT_TP
            , DATA_PRCS_DT
            , DATA_CRT_INTVL_TP
            , DATA_CRT_INTVL_VALUE
            , AUGMENT_STATUS
            , RLS_YN		            
            , REG_USER_SEQ
            , REG_IP
			, DATA_CRT_BGNG_DT
			, DATA_CRT_LAST_DT
            )
       VALUES (
              #{title}
            , #{derpn}
            , #{pprcsSeq}
            , #{modelSeq}
            , #{dataTp}
            , #{augmentTp}
            , #{dataPrcsDt}
            , #{dataCrtIntvlTp}
            , #{dataCrtIntvlValue}
            , #{augmentStatus}
            , #{rlsYn}
            , #{loginUserSeq}
            , #{loginUserIp}
			, #{dataCrtBgngDt}
			, #{dataCrtLastDt}
            )

		SELECT LAST_INSERT_ID()

mapper.update:
/* file : PredictionMapper.xml, id : updateInterpolateFileInfo */
UPDATE TB_AUGMENT
   SET AUGMENT_CRT_BGNG = CURRENT_TIMESTAMP
 WHERE AUGMENT_SEQ   = #{augmentSeq}

/* file : PredictionMapper.xml, id : updateInterpolateFileInfo */
UPDATE TB_AUGMENT
   SET AUGMENT_CRT_END = CURRENT_TIMESTAMP
 WHERE AUGMENT_SEQ   = #{augmentSeq}

/* file : PredictionMapper.xml, id : updateInterpolateFileInfo */
UPDATE TB_AUGMENT
   SET AUGMENT_STATUS = #{augmentStatus}
 WHERE AUGMENT_SEQ   = #{augmentSeq}

/* file : PredictionMapper.xml, id : updateModelInfo */
UPDATE TB_AUGMENT
   SET TITLE = #{title}
     , DERPN = #{derpn}
     , RLS_YN = #{rlsYn}
     , MDFCN_DT	 = CURRENT_TIMESTAMP
	 , MDFCN_IP    = #{loginUserIp}
 WHERE AUGMENT_SEQ   = #{augmentSeq}
   AND DEL_YN = 'N'
   AND USE_YN = 'Y'

/* file : AugmentModelMapper.xml, id : deleteResetFileList */
UPDATE TB_AUGMENT
   SET DEL_USER_SEQ = #{loginUserSeq}
     , DEL_DT	 = CURRENT_TIMESTAMP
	 , DEL_IP    = #{loginUserIp}
	 , DEL_YN = 'Y'
 WHERE AUGMENT_SEQ   = #{augmentSeq}

/* file : AugmentModelMapper.xml, id : deleteResetFileList */
UPDATE TB_AUGMENT_MODEL_FILES
   SET DEL_USER_SEQ = #{loginUserSeq}
     , DEL_DT	 = CURRENT_TIMESTAMP
	 , DEL_IP    = #{loginUserIp}
	 , DEL_YN = 'Y'
 WHERE REF_TP   = 'AUGMENT'
   AND REF_SEQ = #{augmentSeq}
